B.aev=new A.bm("M\u1ee5c \u0111\xe3 l\u01b0u, hi\u1ec7n v\u1eadt v\u1eeba m\u1edf v\xe0 k\u1ebft qu\u1ea3 th\u1eed t\xe0i m\u1eabu ch\u1ec9 gi\u1eef trong phi\xean. L\u01b0\u1ee3t tham quan, \u0111\u01a1n h\xe0ng, \u0111i\u1ec3m v\xe0 huy hi\u1ec7u \u0111\u01b0\u1ee3c t\u1ea3i t\u1eeb h\u1ec7 th\u1ed1ng.",B.E,null)
B.aew=new A.bm("N\u1ebfu \u0111\u1ed9 t\u01b0\u01a1ng \u0111\u1ed3ng ch\u01b0a \u0111\u1ee7 cao, h\u1ec7 th\u1ed1ng s\u1ebd \u0111\u1ec1 ngh\u1ecb x\xe1c nh\u1eadn ho\u1eb7c khuy\u1ebfn ngh\u1ecb qu\xe9t m\xe3 QR c\u1ea1nh hi\u1ec7n v\u1eadt.",B.E,null)
B.aex=new A.bm("Ch\u01b0a c\xf3 tuy\u1ebfn \u0111\xe3 xu\u1ea5t b\u1ea3n ph\xf9 h\u1ee3p.",B.E,null)
B.aey=new A.bm("Ch\u01b0a c\xf3 y\xeau c\u1ea7u thanh to\xe1n.",B.E,null)
B.aez=new A.bm("Ch\u1ec9 chia s\u1ebb m\xe3 v\u1edbi ng\u01b0\u1eddi c\xf9ng nh\xf3m. T\u1ea1o m\xe3 m\u1edbi s\u1ebd thay th\u1ebf m\xe3 c\u0169; th\xe0nh vi\xean nh\u1eadp m\xe3 trong m\u1ee5c D\u1ecbch v\u1ee5 c\u1ee7a t\xf4i.",B.E,null)
B.aeA=new A.bm("Hi\u1ec7n v\u1eadt ch\u01b0a c\xf3 b\u1ea3n thuy\u1ebft minh \u0111\u01b0\u1ee3c xu\u1ea5t b\u1ea3n.",B.E,null)
B.aeB=new A.bm("B\u1ea1n ch\u01b0a l\u01b0u h\xe0nh tr\xecnh c\xe1 nh\xe2n n\xe0o.",B.E,null)
B.aeC=new A.bm("C\xe1c b\u1ea3o t\xe0ng kh\xe1c s\u1ebd xu\u1ea5t hi\u1ec7n khi \u0111\u01b0\u1ee3c c\xf4ng khai tr\xean h\u1ec7 th\u1ed1ng.",B.E,null)
B.aeD=new A.bm("Ch\u01b0a c\xf3 d\u1eef li\u1ec7u.",B.E,null)
B.aeE=new A.bm("B\u1ea1n ch\u01b0a g\u1eedi y\xeau c\u1ea7u n\xe0o.",B.E,null)
B.aeF=new A.bm("D\u1eef li\u1ec7u k\u1ebft n\u1ed1i tr\u1ef1c ti\u1ebfp t\u1eeb m\xe1y ch\u1ee7 Smart Museum Guide System.",B.E,null)
B.aeG=new A.bm("Ch\u01b0a t\u1ea3i \u0111\u01b0\u1ee3c h\xe0nh tr\xecnh \u0111\xe3 l\u01b0u.",B.E,null)
B.aeH=new A.bm("C\xe0i \u0111\u1eb7t v\xe0 d\u1eef li\u1ec7u ch\u1ec9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean tr\u1ea3i nghi\u1ec7m hi\u1ec7n t\u1ea1i.",B.E,null)
B.aeI=new A.bm("Nh\u1eadp m\xe3 do ng\u01b0\u1eddi mua g\xf3i nh\xf3m chia s\u1ebb \u0111\u1ec3 nh\u1eadn quy\u1ec1n truy c\u1eadp.",B.E,null)
B.aeJ=new A.bm("Gi\xe1 v\xe0 th\u1eddi h\u1ea1n \u0111\u01b0\u1ee3c m\xe1y ch\u1ee7 x\xe1c nh\u1eadn khi t\u1ea1o \u0111\u01a1n. Quy\u1ec1n truy c\u1eadp ch\u1ec9 \u0111\u01b0\u1ee3c c\u1ea5p sau khi m\xe1y ch\u1ee7 x\xe1c nh\u1eadn thanh to\xe1n.",B.E,null)
B.aeK=new A.bm("Ch\u01b0a c\xf3 b\u1ea3o t\xe0ng. H\xe3y t\u1ea3i l\u1ea1i danh m\u1ee5c ho\u1eb7c li\xean h\u1ec7 nh\xe2n vi\xean.",B.E,null)
B.aeL=new A.bm("Xem hi\u1ec7n v\u1eadt n\u1eb1m \u1edf ph\xf2ng v\xe0 t\u1ea7ng n\xe0o. Qu\xe9t QR t\u1ea1i v\u1ecb tr\xed \u0111ang \u0111\u1ee9ng \u0111\u1ec3 t\xecm \u0111\u01b0\u1eddng tr\xean s\u01a1 \u0111\u1ed3.",B.E,null)
B.aeM=new A.bm("Ch\u01b0a c\xf3 b\u1ea3o t\xe0ng c\xf4ng khai.",B.E,null)
B.aeN=new A.bm("H\u1ecfi v\u1ec1 hi\u1ec7n v\u1eadt \u0111ang xem. Tr\u1ee3 l\xfd tham kh\u1ea3o n\u1ed9i dung ti\u1ebfng Vi\u1ec7t \u0111\xe3 \u0111\u01b0\u1ee3c b\u1ea3o t\xe0ng xu\u1ea5t b\u1ea3n.",B.E,null)
B.aeO=new A.bm("L\u01b0\u1ee3t tham quan t\u1ef1 do. Qu\xe9t QR t\u1ea1i hi\u1ec7n v\u1eadt \u0111\u1ec3 ghi nh\u1eadn kh\xe1m ph\xe1.",B.E,null)
B.aeP=new A.bm("Ch\u01b0a c\xf3 n\u1ed9i dung c\u1ee7a g\xf3i.",B.E,null)
B.aeQ=new A.bm("C\xe2u h\u1ecfi \u0111\u01b0\u1ee3c m\u1edf sau khi h\u1ec7 th\u1ed1ng ghi nh\u1eadn b\u1ea1n qu\xe9t hi\u1ec7n v\u1eadt c\xf3 b\u1ed9 c\xe2u h\u1ecfi \u0111\xe3 xu\u1ea5t b\u1ea3n.",B.E,null)
B.aeR=new A.bm("Ch\u01b0a c\xf3 quy\u1ec1n truy c\u1eadp \u0111\u01b0\u1ee3c c\u1ea5p.",B.E,null)
B.aeT=new A.bm("B\u1ea1n c\xf3 th\u1ec3 tra c\u1ee9u b\u1ed9 s\u01b0u t\u1eadp m\xe0 kh\xf4ng c\u1ea7n c\u1ea5p quy\u1ec1n m\xe1y \u1ea3nh.",B.E,null)
B.aeU=new A.bm("Tr\u1ea3i nghi\u1ec7m m\xf4 ph\u1ecfng tr\xean web, kh\xf4ng s\u1eed d\u1ee5ng m\xe1y \u1ea3nh.",B.E,null)
B.aeV=new A.bm("Hi\u1ec7n v\u1eadt m\u1eabu ch\u01b0a c\xf3 v\u1ecb tr\xed trong b\u1ea3o t\xe0ng th\u1ef1c t\u1ebf.",B.E,null)
B.aeX=new A.bm("\u0110\xe1nh gi\xe1 b\u1ea3o t\xe0ng c\u1ea7n g\u1eafn v\u1edbi l\u01b0\u1ee3t tham quan \u0111\xe3 ho\xe0n th\xe0nh. G\xf3p \xfd chung s\u1ebd \u0111\u01b0\u1ee3c g\u1eedi \u0111\u1ebfn b\u1ed9 ph\u1eadn h\u1ed7 tr\u1ee3.",B.E,null)
B.aeY=new A.bm("Hi\u1ec7n v\u1eadt ch\u01b0a \u0111\u01b0\u1ee3c li\xean k\u1ebft v\u1edbi \u0111i\u1ec3m \u0111\u1ebfn tr\xean s\u01a1 \u0111\u1ed3 \u0111\xe3 xu\u1ea5t b\u1ea3n.",B.E,null)
B.aeZ=new A.bm("B\u1ea1n c\xf3 th\u1ec3 g\u1eedi v\u1ea5n \u0111\u1ec1 v\u1ec1 d\u1ecbch v\u1ee5 ho\u1eb7c \u0111\u01a1n h\xe0ng. Vi\u1ec7c g\u1eedi y\xeau c\u1ea7u kh\xf4ng t\u1ef1 \u0111\u1ed9ng ho\xe0n ti\u1ec1n; h\u1ec7 th\u1ed1ng ch\u01b0a h\u1ed7 tr\u1ee3 ho\xe0n ti\u1ec1n tr\u1ef1c ti\u1ebfp.",B.E,null)
B.af_=new A.bm("B\u1ea1n ch\u01b0a c\xf3 huy hi\u1ec7u.",B.E,null)
B.af0=new A.bm("\u0110\xe1nh gi\xe1 n\xe0y \u0111\xe3 h\u1ebft th\u1eddi h\u1ea1n ch\u1ec9nh s\u1eeda.",B.E,null)
B.af1=new A.bm("Ch\u01b0a c\xf3 hi\u1ec7n v\u1eadt ph\xf9 h\u1ee3p. Th\u1eed \u0111\u1ed5i t\u1eeb kh\xf3a ho\u1eb7c b\u1ed9 l\u1ecdc.",B.E,null)
